
// ---------- inputs generated by make_bridge.py ----------
double[] PX = new double[]{ -9.73,0.27,10.27,20.27,30.27,40.27,50.27,60.27,70.27,80.27,90.27,100.27,110.27,120.27,130.27,140.27,150.27,160.27,170.27,180.27,190.27,200.27,210.27,220.27,230.27,240.27,250.27,260.27,270.27,280.27,290.27,300.27,310.27,320.27,330.27,340.27,350.27,360.27,370.27,380.27,390.27,400.27,410.27,420.27,430.27,440.27,450.27,460.27,470.27,480.27,490.27,500.27,510.27,520.27,530.27,540.27,550.27,560.27,570.27,580.27,590.27,600.27,610.27,620.27,630.27,640.27,650.27,660.27,670.27,680.27,690.27,700.27,710.27,720.27,730.27 };
double[] PZ = new double[]{ 419.720,419.063,418.422,417.797,417.187,416.593,416.015,415.451,414.904,414.372,413.855,413.355,412.869,412.399,411.945,411.506,411.083,410.676,410.284,409.907,409.546,409.201,408.871,408.556,408.257,407.974,407.707,407.454,407.218,406.997,406.791,406.601,406.427,406.268,406.124,405.997,405.884,405.786,405.689,405.592,405.496,405.399,405.302,405.206,405.109,405.012,404.915,404.819,404.722,404.625,404.529,404.432,404.335,404.239,404.142,404.045,403.948,403.852,403.755,403.658,403.562,403.465,403.368,403.271,403.175,403.078,402.981,402.885,402.788,402.691,402.595,402.498,402.401,402.312,402.238 };
double FG(double x){ if(x<=PX[0]) return PZ[0]; for(int i=1;i<PX.Length;i++) if(x<=PX[i]) return PZ[i-1]+(PZ[i]-PZ[i-1])*(x-PX[i-1])/(PX[i]-PX[i-1]); return PZ[PX.Length-1]; }
// ---------- constants (ft) ----------
double SLAB=9.5/12, HAUNCH=2.0/12, GD=110.0/12;          // slab, haunch, girder depth (106" web + flanges, assumed)
double YL=22.0, YR=-31.0;                                  // deck edges, left +
double[] GY = { 18.667, 7.083, -4.5, -16.083, -27.667 };   // girder lines (3'-4", 11'-7", 7'-1"|4'-6", 2 @ 11'-7")
double XA=7.49, X1=277.49, X2=488.89, XB=708.89;           // CL bearing Abut A, Pier 1, Pier 2, Abut B
double LEN=715.98;                                         // back of backwall to back of backwall
double SKEW = 10.0*Math.PI/180;                            // substructure skew
string log="";

Material Mat(string name, byte r, byte g, byte b){
  var m = new FilteredElementCollector(document).OfClass(typeof(Material)).Cast<Material>().FirstOrDefault(q=>q.Name==name);
  if(m!=null) return m; var id=Material.Create(document,name); m=(Material)document.GetElement(id); m.Color=new Color(r,g,b); return m; }
var conc=Mat("B676 Concrete Class A4",190,190,185); var steel=Mat("B676 Steel A709 Gr50W (weathering)",120,70,45);
var mse=Mat("B676 MSE Wall Panels",170,160,140); var shaft=Mat("B676 Concrete Class A3 (drilled shaft)",150,150,150);

XYZ P(double x,double y,double z)=>new XYZ(x,y,z);
// skewed plan point about a substructure line at station xs: u along the skew line (left +), v normal (ahead +)
CurveLoop Loop(IList<XYZ> pts){ var cl=new CurveLoop(); for(int i=0;i<pts.Count;i++) cl.Append(Line.CreateBound(pts[i],pts[(i+1)%pts.Count])); return cl; }
Solid Box(IList<XYZ> plan, double z0, double z1, Material m){ var pp=plan.Select(p=>new XYZ(p.X,p.Y,z0)).ToList(); return GeometryCreationUtilities.CreateExtrusionGeometry(new List<CurveLoop>{Loop(pp)}, XYZ.BasisZ, z1-z0, new SolidOptions(m.Id, ElementId.InvalidElementId)); }
Solid Cyl(XYZ c, double r, double z0, double z1, Material m){ var cl=new CurveLoop(); var a=Arc.Create(new XYZ(c.X,c.Y,z0),r,0,Math.PI,XYZ.BasisX,XYZ.BasisY); var b=Arc.Create(new XYZ(c.X,c.Y,z0),r,Math.PI,2*Math.PI,XYZ.BasisX,XYZ.BasisY); cl.Append(a); cl.Append(b);
  return GeometryCreationUtilities.CreateExtrusionGeometry(new List<CurveLoop>{cl}, XYZ.BasisZ, z1-z0, new SolidOptions(m.Id, ElementId.InvalidElementId)); }
// a prism between two cross sections (y,z lists) at x0 and x1: section points are (y, dz) relative to f(x)
Solid Loft(double x0,double x1,Func<double,IList<XYZ>> sec, Material m){
  var l0=Loop(sec(x0)); var l1=Loop(sec(x1)); return GeometryCreationUtilities.CreateLoftGeometry(new List<CurveLoop>{l0,l1}, new SolidOptions(m.Id, ElementId.InvalidElementId)); }
DirectShape DS(BuiltInCategory cat, string name, string mark, string comments, IList<GeometryObject> g){
  var ds=DirectShape.CreateElement(document,new ElementId(cat)); ds.ApplicationId="BerkmarB676"; ds.ApplicationDataId=mark; ds.SetShape(g); ds.SetName(name);
  ds.get_Parameter(BuiltInParameter.ALL_MODEL_MARK)?.Set(mark); ds.get_Parameter(BuiltInParameter.ALL_MODEL_INSTANCE_COMMENTS)?.Set(comments);
  log+=mark+" "; return ds; }
List<double> Stations(double a,double b,double step){ var s=new List<double>(); for(double x=a;x<b-1e-6;x+=step) s.Add(x); s.Add(b); return s; }

// ---------- remove a previous build ----------
var old=new FilteredElementCollector(document).OfClass(typeof(DirectShape)).Cast<DirectShape>().Where(d=>d.ApplicationId=="BerkmarB676").Select(d=>d.Id).ToList();
document.Delete(old);

// ---------- deck slab (crowned, 2% each way, follows the profile grade line) ----------
IList<XYZ> DeckSec(double x){ double f=FG(x); return new List<XYZ>{ P(x,YL,f-0.02*YL), P(x,0,f), P(x,YR,f+0.02*YR), P(x,YR,f+0.02*YR-SLAB), P(x,0,f-SLAB), P(x,YL,f-0.02*YL-SLAB) }; }
var st=Stations(0,LEN,20); var deck=new List<GeometryObject>(); for(int i=0;i<st.Count-1;i++) deck.Add(Loft(st[i],st[i+1],DeckSec,conc));
DS(BuiltInCategory.OST_Floors,"Deck Slab 9.5in","DECK","4D: 08 Deck pour",deck);

// sidewalk (6", left) and BR27C parapets + median rail
double Top(double x,double y)=>FG(x)-0.02*Math.Abs(y);
var sw=new List<GeometryObject>(); for(int i=0;i<st.Count-1;i++) sw.Add(Loft(st[i],st[i+1],x=>new List<XYZ>{P(x,15,Top(x,15)),P(x,21,Top(x,21)),P(x,21,Top(x,21)+0.5),P(x,15,Top(x,15)+0.5)},conc));
DS(BuiltInCategory.OST_Floors,"Raised Sidewalk 6ft","SIDEWALK","4D: 09 Parapets and sidewalk",sw);
foreach(var r in new[]{ (21.0,22.0,"RAIL-LT"), (-15.0,-16.0,"RAIL-MED"), (-30.0,-31.0,"RAIL-RT") }){
  var g=new List<GeometryObject>(); double hgt = r.Item3=="RAIL-LT" ? 3.17 : 2.67;
  for(int i=0;i<st.Count-1;i++) g.Add(Loft(st[i],st[i+1],x=>new List<XYZ>{P(x,r.Item1,Top(x,r.Item1)),P(x,r.Item2,Top(x,r.Item2)),P(x,r.Item2,Top(x,r.Item2)+hgt),P(x,r.Item1,Top(x,r.Item1)+hgt)},conc));
  DS(BuiltInCategory.OST_GenericModel,"BR27C Parapet Rail",r.Item3,"4D: 09 Parapets and sidewalk",g); }

// ---------- 5 steel plate girders (I-shape lofted along the profile) ----------
double GT(double x,double y)=>Top(x,y)-SLAB-HAUNCH;   // top of top flange
var gst=Stations(XA-1.5,XB+1.5,20);
for(int k=0;k<5;k++){ double y=GY[k]; var g=new List<GeometryObject>();
  IList<XYZ> Isec(double x){ double t=GT(x,y); double tf=1.5/12, bf=2.5/12, wt=0.75/12, wt2=wt/2, bt=20.0/12/2, bb=24.0/12/2, b=t-GD;
    return new List<XYZ>{ P(x,y-bt,t),P(x,y+bt,t),P(x,y+bt,t-tf),P(x,y+wt2,t-tf),P(x,y+wt2,b+bf),P(x,y+bb,b+bf),P(x,y+bb,b),P(x,y-bb,b),P(x,y-bb,b+bf),P(x,y-wt2,b+bf),P(x,y-wt2,t-tf),P(x,y-bt,t-tf) }; }
  for(int i=0;i<gst.Count-1;i++) g.Add(Loft(gst[i],gst[i+1],Isec,steel));
  DS(BuiltInCategory.OST_StructuralFraming,"Steel Plate Girder "+(k+1),"G"+(k+1),"4D: 07 Steel erection",g); }

// ---------- substructure on a 10 deg skew ----------
// skew line through (xs, y=0): direction d = (sin S, cos S) for u (left +); normal n = (cos S, -sin S) for v (ahead +)
XYZ Q(double xs,double u,double v,double z)=>new XYZ(xs + u*Math.Sin(SKEW) + v*Math.Cos(SKEW), u*Math.Cos(SKEW) - v*Math.Sin(SKEW), z);
List<XYZ> Rect(double xs,double u0,double u1,double v0,double v1)=>new List<XYZ>{Q(xs,u0,v0,0),Q(xs,u1,v0,0),Q(xs,u1,v1,0),Q(xs,u0,v1,0)};
double GirderBottomAt(double x)=>GT(x,-4.5)-GD;
string[] pierNames={"PIER 1","PIER 2"}; double[] pierX={X1,X2};
for(int p=0;p<2;p++){ double xs=pierX[p]; double capTop=GirderBottomAt(xs)-0.5, capBot=capTop-5.25; string tag="P"+(p+1);
  // cap 56'-6" x 6'-6": 23'-8 1/8" left of CL, 32'-9 7/8" right
  DS(BuiltInCategory.OST_StructuralFraming,pierNames[p]+" Cap",tag+"-CAP","4D: 05 Pier caps",new List<GeometryObject>{Box(Rect(xs,23.677,-32.823,-3.25,3.25),capBot,capTop,conc)});
  double uc=(23.677-32.823)/2; // cap centre
  for(int c=0;c<3;c++){ double u=uc+(c-1)*18.0; var cxy=Q(xs,u,0,0);
    DS(BuiltInCategory.OST_StructuralColumns,pierNames[p]+" Column "+(c+1)+" (6'-0\" dia)",tag+"-COL"+(c+1),"4D: 04 Pier columns",new List<GeometryObject>{Cyl(cxy,3.0,342.5,capBot,conc)});
    DS(BuiltInCategory.OST_StructuralFoundation,pierNames[p]+" Drilled Shaft "+(c+1)+" (7'-0\" dia)",tag+"-DS"+(c+1),"4D: 02 Drilled shafts",new List<GeometryObject>{Cyl(cxy,3.5,310.0,342.5,shaft)}); }
  log+="["+tag+" capTop="+capTop.ToString("F2")+"] "; }

// abutments: seat + backwall on HP piles, fronted by an MSE wall; MSE wingwalls along the approach fill
double[] abX={0.0,LEN}; double[] brX={XA,XB}; string[] abN={"ABUTMENT A","ABUTMENT B"}; double[] ground={392.0,379.5};
for(int a=0;a<2;a++){ double xb=abX[a]; double sgn=a==0?1:-1; string tag=a==0?"AA":"AB";
  double seatTop=GirderBottomAt(brX[a])-0.5, seatBot=seatTop-4.0;
  double bw0=0, bw1=1.69*sgn;              // backwall: back of backwall to face of backwall
  double s0=1.69*sgn, s1=11.5*sgn;          // seat beam
  DS(BuiltInCategory.OST_StructuralFoundation,abN[a]+" Seat",tag+"-SEAT","4D: 03 Abutments",new List<GeometryObject>{Box(Rect(xb,YL+1.5,YR-1.5,Math.Min(s0,s1),Math.Max(s0,s1)),seatBot,seatTop,conc)});
  DS(BuiltInCategory.OST_Walls,abN[a]+" Backwall",tag+"-BKWL","4D: 03 Abutments",new List<GeometryObject>{Box(Rect(xb,YL+1.5,YR-1.5,Math.Min(bw0,bw1),Math.Max(bw0,bw1)),seatBot,Top(xb,0)-SLAB,conc)});
  var piles=new List<GeometryObject>(); for(int i=0;i<12;i++){ double u=YL-1.5-i*(YL-YR-3)/11.0; foreach(double v in new[]{4.5*sgn,8.5*sgn}){ var c=Q(xb,u,v,0); piles.Add(Box(new List<XYZ>{new XYZ(c.X-0.5,c.Y-0.5,0),new XYZ(c.X+0.5,c.Y-0.5,0),new XYZ(c.X+0.5,c.Y+0.5,0),new XYZ(c.X-0.5,c.Y+0.5,0)},seatBot-45,seatBot,steel)); } }
  DS(BuiltInCategory.OST_StructuralFoundation,abN[a]+" HP14x89 Piles (24)",tag+"-PILES","4D: 01 Abutment piles",piles);
  // MSE abutment wall face just in front of the seat, ground to seat bottom
  double f0=s1, f1=s1+1.0*sgn; DS(BuiltInCategory.OST_Walls,abN[a]+" MSE Abutment Wall",tag+"-MSE","4D: 03 Abutments",new List<GeometryObject>{Box(Rect(xb,YL+4,YR-4,Math.Min(f0,f1),Math.Max(f0,f1)),ground[a]-2,seatBot,mse)});
  // MSE wingwalls: 60 ft back along the approach on both sides, stepping down
  foreach(var side in new[]{(YL+3.0,YL+4.0,"L"),(YR-4.0,YR-3.0,"R")}){ var w=new List<GeometryObject>();
    for(int s=0;s<6;s++){ double xa=xb-sgn*s*10, xc=xb-sgn*(s+1)*10; double zt=Top(Math.Min(xa,xc),0)-1.0;
      var pl=new List<XYZ>{P(Math.Min(xa,xc),side.Item1,0),P(Math.Max(xa,xc),side.Item1,0),P(Math.Max(xa,xc),side.Item2,0),P(Math.Min(xa,xc),side.Item2,0)};
      w.Add(Box(pl,ground[a]-2+s*2.5,zt,mse)); }
    DS(BuiltInCategory.OST_Walls,abN[a]+" MSE Wingwall "+side.Item3,tag+"-WW"+side.Item3,"4D: 06 MSE wingwalls and backfill",w); } }

// ---------- approach slabs (25 ft) ----------
foreach(var a in new[]{(-25.0,0.0,"APP-A"),(LEN,LEN+25.0,"APP-B")}){ var g=new List<GeometryObject>{Loft(a.Item1,a.Item2,x=>new List<XYZ>{P(x,YL,Top(x,YL)-0.05),P(x,0,FG(x)-0.05),P(x,YR,Top(x,YR)-0.05),P(x,YR,Top(x,YR)-1.05),P(x,0,FG(x)-1.05),P(x,YL,Top(x,YL)-1.05)},conc)};
  DS(BuiltInCategory.OST_Floors,"Approach Slab 12in",a.Item3,"4D: 10 Approach slabs",g); }
return log;